package com.tainted.community.blackbox;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.hamcrest.Matchers.nullValue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api GET /internal/posts/{id}
 *
 * 분석 요약 (NIMBUS 파이프라인 산출물 기반):
 * - analyze-auth-flow: auth_type=none, required_headers=[] → 인증 헤더 불필요
 * - detect-external-calls(--include-di-analysis): external_calls=[] → WireMock 스텁 불필요
 *   (CommunityService.getPost → PostRepository.findById 만 호출, 외부 HTTP/MQ 연동 없음)
 * - analyze-test-data: 대상 테이블 post(id, user_id, title, category, content, mood_emoji,
 *   nickname, likes, created_at) — PostRepository 는 JPA 이므로 setup/teardown 은 이 테이블만 다룬다.
 *
 * VTC 표준 rule 적용/제외 사유 (id 는 RED 파라미터, DB_WHERE 등가비교):
 * - NULL: 제외. id 는 필수 @PathVariable 이며, 세그먼트를 생략하면 GET /internal/posts
 *   (listPosts, 별개 핸들러) 로 라우팅되어 getPost 핸들러 자체에 도달하지 않는다.
 * - EMPTY: 제외. 완전한 빈 세그먼트("/internal/posts/")는 Spring 이 getPost 로 매핑하지 않는다
 *   (별도 라우트로 처리됨). 대신 공백 1문자를 EMPTY 에 준하는 경계값으로 WHITE_SPACE 케이스에서 다룬다.
 * - WHITE_SPACE: 적용 (VTC_id_WHITE_SPACE).
 * - SPECIAL_CHAR: 적용 (VTC_id_SPECIAL_CHAR) — JPA/Hibernate 파라미터 바인딩 검증.
 * - LENGTH_EXCEEDED: 적용 (VTC_id_LENGTH_EXCEEDED) — post.id 컬럼은 VARCHAR(64) 이므로 64자
 *   초과 id 는 어떤 저장된 row 와도 일치할 수 없다 (조회 전용이라 write 제약과 무관하게 안전하게 검증 가능).
 * - LENGTH_SHRUNK: 제외. id 컬럼에 최소 길이 제약이 없다 (boundary 힌트 없음).
 * - INVALID_FORMAT: 제외. id 는 순수 문자열이며 날짜/숫자 파싱 로직이 없다.
 *
 * ATC_code400 (extract-test-scenarios 산출물의 일반 400 케이스) 매핑:
 * getPost 핸들러는 요청 바디/검증 로직이 없어(@Valid 없음) 애플리케이션 레벨 400 을
 * 유발할 방법이 없다. 대신 이 핸들러가 실제로 도달 가능한 유일한 400 경로인 서블릿 컨테이너
 * 레벨의 잘못된 percent-encoding 요청(Tomcat 이 URI 디코딩 단계에서 400 을 반환)으로 매핑한다.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class InternalPostsByIdBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8085");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/community");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static Map<String, String> baseParams(String id) {
        Map<String, String> params = new HashMap<>();
        params.put("ID", id);
        params.put("USER_ID", id + "-user");
        params.put("TITLE", "Weekly reflection " + id);
        params.put("CATEGORY", "career");
        params.put("CONTENT", "content body for " + id);
        params.put("MOOD_EMOJI_LITERAL", "'🙂'");
        params.put("NICKNAME", "nick-" + id);
        params.put("LIKES", "5");
        params.put("CREATED_AT", "2026-01-10 09:15:00");
        return params;
    }

    @Test
    void NTC_getPost_success(TestInfo info) throws Exception {
        String id = testId(info);
        Map<String, String> params = baseParams(id);

        executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", params);
        executeSqlTemplate("sql/internal-posts-by-id-setup.sql", params);

        try {
            given().log().all()
                .baseUri(BASE_URL)
            .when()
                .get("/internal/posts/{id}", id)
            .then().log().all()
                .statusCode(200)
                .contentType(ContentType.JSON)
                .body("id", equalTo(id))
                .body("userId", equalTo(id + "-user"))
                .body("title", equalTo("Weekly reflection " + id))
                .body("category", equalTo("career"))
                .body("content", equalTo("content body for " + id))
                .body("moodEmoji", equalTo("🙂"))
                .body("nickname", equalTo("nick-" + id))
                .body("likes", equalTo(5))
                .body("createdAt", matchesPattern("2026-01-10T09:15:00(\\.\\d+)?Z"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", params);
        }
    }

    @Test
