276	            for (Map.Entry<String, String> entry : params.entrySet()) {
277	                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
278	            }
279	            for (String line : sql.split("\n")) {
280	                String trimmed = line.trim();
281	                if (trimmed.startsWith("--") || trimmed.isEmpty()) {
282	                    continue;
283	                }
284	                if (trimmed.endsWith(";")) {
285	                    trimmed = trimmed.substring(0, trimmed.length() - 1);
286	                }
287	                if (!trimmed.isEmpty()) {
288	                    stmt.execute(trimmed);
289	                }
290	            }
291	        } catch (Exception e) {
292	            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
293	        }
294	    }
