297	        java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();
298	        byte[] data = new byte[4096];
299	        int read;
300	        while ((read = is.read(data, 0, data.length)) != -1) {
301	            buffer.write(data, 0, read);
302	        }
